package com.oldschoolnetwork.lite;
import android.app.*;import android.content.*;import android.os.*;import android.view.View;import android.widget.*;import org.json.JSONObject;import org.json.JSONArray;
/** Independent Lite channels; release assets are fetched directly without a GitHub API token. */
public final class OfficialDownloadActivity extends Activity {
 private JSONObject release;private String name;private TextView status;private boolean listening;
 private static final String CERT="f8239cd9deb269e9d4d86893732c27def1936737539c31983d75f1251a49f2d2";
 private final BroadcastReceiver updates=new BroadcastReceiver(){public void onReceive(Context c,Intent i){render();}};
 public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.lite_official_download);status=(TextView)findViewById(R.id.official_status);final boolean core=!"store".equals(getIntent().getStringExtra("service"));name=core?"com.oldschoolnetwork.core.lite":"com.oldschoolnetwork.store.lite";
  ((TextView)findViewById(R.id.official_title)).setText(core?"ON Core Lite":"ON Store Lite");findViewById(R.id.official_action).setEnabled(false);findViewById(R.id.official_close).setOnClickListener(new View.OnClickListener(){public void onClick(View v){finish();}});findViewById(R.id.official_action).setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(release==null)return;try{if("ready".equals(Transfers.phase(OfficialDownloadActivity.this,name)))Transfers.install(OfficialDownloadActivity.this,name);else if(Transfers.installed(OfficialDownloadActivity.this,name)>=release.optInt("version_code")){Intent launch=getPackageManager().getLaunchIntentForPackage(name);if(launch!=null)startActivity(launch);}else startService(new Intent(OfficialDownloadActivity.this,Transfers.class).putExtra("package",name).putExtra("release",release.toString()));}catch(Exception error){status.setText(error.getMessage());}}});
  try{release=new JSONObject(getSharedPreferences("official",0).getString(name,""));if(!name.equals(release.optString("package_name"))||!CERT.equals(release.optString("certificate_sha256")))release=null;else render();}catch(Exception ignored){release=null;}
  final Handler ui=new Handler();Api.WORK.execute(new Runnable(){public void run(){try{final JSONObject manifest=fetchReleaseManifest(OfficialDownloadActivity.this,core?"core-lite":"store-lite");if(!name.equals(manifest.optString("package_name"))||!CERT.equals(manifest.optString("certificate_sha256"))||manifest.optInt("min_sdk",999)>Build.VERSION.SDK_INT||!manifest.optString("sha256").matches("[0-9a-f]{64}"))throw new Exception("The release manifest is not valid for this Lite service.");ui.post(new Runnable(){public void run(){if(isFinishing())return;release=manifest;getSharedPreferences("official",0).edit().putString(name,manifest.toString()).commit();render();}});}catch(final Exception error){ui.post(new Runnable(){public void run(){if(!isFinishing())status.setText("Could not check this Lite release. "+error.getMessage());}});}}});
 }
 public static JSONObject fetchReleaseManifest(Context context,String repository)throws Exception {
  if(!repository.equals("core-lite")&&!repository.equals("store-lite"))throw new Exception("Unknown Lite channel.");
  JSONArray releases=new JSONArray(new String(HttpsTransport.request(context,"https://api.github.com/repos/OldschoolNetwork/"+repository+"/releases?per_page=10",null,262144),"UTF-8"));
  for(int i=0;i<releases.length();i++){JSONObject release=releases.getJSONObject(i);if(release.optBoolean("draft"))continue;JSONArray assets=release.optJSONArray("assets");if(assets==null)continue;
   for(int n=0;n<assets.length();n++){JSONObject asset=assets.getJSONObject(n);String url=asset.optString("browser_download_url");if(asset.optString("name").equals("on-release.json")&&url.startsWith("https://github.com/OldschoolNetwork/"+repository+"/releases/download/"))return new JSONObject(new String(HttpsTransport.request(context,url,null,32768),"UTF-8"));}
  }
  throw new Exception("No published Lite release manifest is available.");
 }
 private void render(){if(release==null)return;String phase=Transfers.phase(this,name);boolean busy="downloading".equals(phase)||"installing".equals(phase);ProgressBar progress=(ProgressBar)findViewById(R.id.official_progress);progress.setVisibility(busy?View.VISIBLE:View.GONE);progress.setIndeterminate("installing".equals(phase));progress.setProgress(getSharedPreferences("transfers",0).getInt(name+".progress",0));Button action=(Button)findViewById(R.id.official_action);action.setEnabled(!busy);action.setText("ready".equals(phase)?"Install":"installing".equals(phase)?"Installing…":"downloading".equals(phase)?"Downloading…":Transfers.installed(this,name)>=release.optInt("version_code")?"Open":"Download");status.setText("Version "+release.optString("version_name")+"\n"+getSharedPreferences("transfers",0).getString(name+".message","Downloaded directly from Oldschool Network on GitHub. APK signatures and checksums are verified."));}
 protected void onResume(){super.onResume();registerReceiver(updates,new IntentFilter(getPackageName()+".TRANSFER"));listening=true;render();}
 protected void onPause(){if(listening)unregisterReceiver(updates);listening=false;super.onPause();}
}
